sys_variable_value.value:
(function execute(inputs, outputs) {

    var claim = new GlideRecord('x_snc_insurance_0_claim');

    // Find claim using Claim Number
    claim.addQuery('claim_number', inputs.claim_number);
    claim.query();

    if (!claim.next()) {
        throw new Error('Claim ' + inputs.claim_number + ' not found.');
    }

    var enteredOtp = (inputs.otp_entered || '').toString();
    var storedOtp = (claim.getValue('otp_code') || '').toString();

    // Save entered OTP
    claim.setValue('otp_entered', enteredOtp);

    // Compare OTP
    if (enteredOtp && storedOtp && enteredOtp === storedOtp) {

        claim.setValue('otp_verified', true);
        claim.update();

        outputs.verification_result =
            'OTP verified successfully for claim ' +
            claim.getValue('claim_number');

    } else {

        claim.setValue('otp_verified', false);
        claim.update();

        outputs.verification_result =
            'Invalid OTP for claim ' +
            claim.getValue('claim_number');
    }

})(inputs, outputs);

